 });
+
+test("findByTag matches tags beyond the first", async () => {
+  const item = await addItem({ name: "cheese", tags: ["dairy", "fridge"] });
+  const matches = await findByTag("fridge");
+  assert.ok(matches.some((match) => match.id === item.id));
+});
